menu={}function menu:FlyIn(dir)	if dir=='left' then self.x=screen.width*0.5-700 elseif dir=='right' then self.x=screen.width*0.5+700 end	task.Clear(self)	task.New(self,function()		task.MoveTo(screen.width*0.5,self.y,30,2)		self.locked=false	end)endfunction menu:FlyOut(dir)	local x	if dir=='left' then x=screen.width*0.5-700 elseif dir=='right' then x=screen.width*0.5+700 end	task.Clear(self)	if not self.locked then		task.New(self,function()			self.locked=true			task.MoveTo(x,self.y,30,1)		end)	endendfunction menu:PlayerFlyIn(dir)	local x	if dir=='left' then x=screen.width*0.5-200 end	if dir=='right' then x=screen.width*0.5-100 end	if dir=='mid' then x=screen.width*0.5-150 end	if dir=='mid' then	    task.New(self,function()	    	self.alphanow=self.alpha	    	for i=0,14 do	    		self.alpha=self.alphanow+(1-self.alphanow)*i/14	    		self.R=self.alphanow+(1-self.alphanow)*i/14	    		self.G=self.alphanow+(1-self.alphanow)*i/14	    		self.B=self.alphanow+(1-self.alphanow)*i/14	    		task.Wait()	    	end	    end)	else	    task.New(self,function()	    	self.alphanow=self.alpha	    	for i=0,14 do	    		self.alpha=self.alphanow+(0-self.alphanow)*i/14	    		self.R=self.alphanow+(1-self.alphanow)*i/14	    		self.G=self.alphanow+(1-self.alphanow)*i/14	    		self.B=self.alphanow+(1-self.alphanow)*i/14	    		task.Wait()	    	end	    end)	end	task.New(self,function()		task.MoveTo(x,self.y,15,1)		self.locked=false	end)endfunction menu:HscaleIn(dir)	self.x=screen.width*0.5+150	if dir=='in' then	    task.New(self,function()	    	self.alphanow=self.alpha	    	for i=0,14 do	    		self.alpha=self.alphanow+(1-self.alphanow)*sin(i/14*90)	    		self.Hscale=self.alphanow+(1-self.alphanow)*sin(i/14*90)	    		task.Wait()	    	end	    end)	else	    task.New(self,function()	    	self.alphanow=self.alpha	    	for i=0,14 do	    		self.alpha=self.alphanow+(0-self.alphanow)*sin(i/14*90)	    		self.Hscale=self.alphanow+(0-self.alphanow)*sin(i/14*90)	    		task.Wait()	    	end	    end)	endendfunction menu:RotatingIn(dir)	self.x=screen.width*0.5+5	task.New(self,function()		for i=0,6 do			self.alpha=i/6			self.Hscale=i/6			if dir=='left' then self.rot=18*sin(90*i/6)-180 elseif dir=='right' then self.rot=-180*sin(90*i/6)+180 end			task.Wait()		end		self.locked=false	end)endfunction menu:RotatingOut(dir)    if not self.locked then		task.New(self,function()			self.locked=true			for i=6,0,-1 do				self.Hscale=i/6				self.alpha=i/6				if dir=='left' then self.rot=180*sin(90*i/6)-180 elseif dir=='right' then self.rot=-180*sin(90*i/6)+180 end				task.Wait()			end		end)	endendfunction menu:Rotating()	task.New(self,function()	    task.Wait(10)		for i=0,9000 do			self.rot=5*sin(5*i) 			task.Wait()		end	end)endfunction menu:LogoRotating(dir)	self.x=screen.width*0.5-150	self.y=screen.height*0.5+120	if dir=='left' then self.rot=119 else self.rot=-119 end	task.New(self,function()		for i=119,0,-1 do			self.alpha=(119-i)/119			if dir=='left' then self.rot=self.rot-i/60 else self.rot=self.rot+i/60 end 			task.Wait()		end		self.rot=0	end)endfunction menu:LogoHscale()	self.x=screen.width*0.5-150	self.y=screen.height*0.5+120	task.New(self,function()		for i=0,14 do			self.alpha=i/14			self.Hscale=(28-i)/14/2			self.Vscale=(28-i)/14/2 			task.Wait()		end		self.locked=false	end)endfunction menu:BlackOut(dir)	task.Clear(self)	if dir=='ranksave' and not self.locked  then		task.New(self,function()			self.locked=true		    for i=2,0,-1 do			    for a=0,5 do				    self.alpha=i/4*(sin(a*90)/2+1/2)				    self.R=i/2/4+3/4				    self.G=i/2/4+3/4				    self.B=i/2/4+3/4			        task.Wait()				end				task.Wait()		    end			self.alpha=1			self.imglock=true			task.New(self,function()			    for i=0,4 do				    self.alpha=i/4					task.Wait()				end			end)			task.New(self,function()			    for i=14,0,-1 do				    self.Hscale=i/14/3+2/3					self.Vscale=i/14/3+2/3					task.Wait()				end			end)			task.MoveTo(screen.width*0.5,screen.height*0.5-200,15,2)		    self.locked=false		end)    end	if dir=='stagesave' and not self.locked  then		task.New(self,function()			self.locked=true		    for i=2,0,-1 do			    for a=0,5 do				    self.alpha=i/4*(sin(a*90)/2+1/2)				    self.R=i/2/4+3/4				    self.G=i/2/4+3/4				    self.B=i/2/4+3/4			        task.Wait()				end				task.Wait()		    end			self.alpha=1			self.imglock=true			task.New(self,function()			    for i=0,4 do				    self.alpha=i/4					task.Wait()				end			end)			task.New(self,function()			    for i=14,0,-1 do				    self.Hscale=i/14/3+2/3					self.Vscale=i/14/3+2/3					task.Wait()				end			end)			task.MoveTo(screen.width*0.5+200,screen.height*0.5-200,15,2)		    self.locked=false		end)    end	if dir=='nomal' and not self.locked  then    	if not self.locked then    	    task.New(self,function()    			self.locked=true	    	    for i=2,0,-1 do	    		    for a=0,5 do	    			    self.alpha=i/4*(sin(a*90)/2+1/2)	    			    self.R=i/2/4+3/4	    			    self.G=i/2/4+3/4	    			    self.B=i/2/4+3/4	    		        task.Wait()	    			end	    			task.Wait()	    	    end	    	    self.locked=false	    	end)	    end	endendfunction menu:FadeIn()	self.x=screen.width*0.5	task.Clear(self)	task.New(self,function()		for i=0,14 do			self.alpha=i/14			task.Wait()		end		self.locked=false	end)endfunction menu:FadeOut()	task.Clear(self)	if not self.locked then		task.New(self,function()			self.locked=true			for i=14,0,-1 do				self.alpha=i/14				task.Wait()			end		end)	endendfunction menu:AddFadeIn()	self.x=screen.width*0.5	task.Clear(self)	task.New(self,function()		if self.alpha<1 then		    for i=0,9 do			    self.alpha=i/9			    task.Wait()			end		end		self.locked=false	end)endfunction menu:AddFadeOut()	task.Clear(self)	if not self.locked then		task.New(self,function()			self.locked=true			if self.alpha>0 then				for i=9,0,-1 do			    	self.alpha=i/94		    		task.Wait()				end			end		end)	endendfunction menu:RankFlyIn(dir)	self.alpha=1	local x,y	if dir=='up' then x=screen.width*0.5-150 y=screen.height*0.5+100 end	if dir=='mid' then x=screen.width*0.5 y=screen.height*0.5 end	if dir=='down' then x=screen.width*0.5+150 y=screen.height*0.5-100 end	if dir=='out' then x=screen.width*0.5 y=screen.height*0.5-100 end	if dir=='mid' then	    self.layer=LAYER_TOP+2		task.New(self,function()		    self.Hsclaenow=self.Hscale	    	for i=0,14 do	     		self.Hscale=self.Hsclaenow+(1-self.Hsclaenow)*sin(90*i/14)	     		self.Vscale=self.Hsclaenow+(1-self.Hsclaenow)*sin(90*i/14)	    		task.Wait()	    	end		end)	end	task.New(self,function()		task.MoveTo(x,y,15,2)		self.R=1		self.G=1		self.B=1		self.locked=false		self.imglock=false	end)	if dir=='out' then	    task.New(self,function()	    	for i=14,0,-1 do	     		self.alpha=i/14	    		task.Wait()	    	end	    	self.locked=false	    end)	else		task.New(self,function()		    if self.alpha<1 then		        for i=0,14 do		    	    self.alpha=i/14		    	    task.Wait()		    	end		    end		    self.locked=false	    end)	endendfunction menu:StageFlyIn(dir,_y)    self.imglock=false	local x,y	if dir=='right' then x=screen.width*0.5+300 y=screen.height*0.5+_y*0.5 end	if dir=='mid' then x=screen.width*0.5 y=screen.height*0.5+_y end	if dir=='left' then x=screen.width*0.5-300 y=screen.height*0.5+_y*0.5 end	if dir=='rightout' then x=screen.width*0.5+250*1.5 y=screen.height*0.5+_y*0.5 end	if dir=='leftout' then x=screen.width*0.5-250*1.5 y=screen.height*0.5+_y*0.5 end	if dir=='mid' then	    self.layer=LAYER_TOP+2		task.New(self,function()		    self.Hsclaenow=self.Hscale	    	for i=0,29 do	     		self.Hscale=self.Hsclaenow+(1-self.Hsclaenow)*sin(90*i/29)	     		self.Vscale=self.Hsclaenow+(1-self.Hsclaenow)*sin(90*i/29)	    		task.Wait()	    	end		end)    else	    self.layer=LAYER_TOP		task.New(self,function()		    self.Hsclaenow=self.Hscale	    	for i=0,29 do	     		self.Hscale=self.Hsclaenow+(1/2-self.Hsclaenow)*sin(90*i/29)	     		self.Vscale=self.Hsclaenow+(1/2-self.Hsclaenow)*sin(90*i/29)	    		task.Wait()	    	end		end)	end	task.New(self,function()		task.MoveTo(x,y,30,2)		self.R=1		self.G=1		self.B=1	end)	if dir=='rightout' or dir=='leftout' then	    task.New(self,function()		    self.alphanow=self.alpha	    	for i=0,29 do	     		self.alpha=self.alphanow+(0-self.alphanow)*i/29	    		task.Wait()	    	end	    	self.locked=false	    end)	end	if dir=='right' or dir=='left' then	    task.New(self,function()		    self.alphanow=self.alpha	    	for i=0,29 do	     		self.alpha=self.alphanow+(1/3-self.alphanow)*i/29	    		task.Wait()	    	end	    	self.locked=false	    end)	end	if dir=='mid' then	    task.New(self,function()		    self.alphanow=self.alpha	    	for i=0,29 do	     		self.alpha=self.alphanow+(1-self.alphanow)*i/29	    		task.Wait()	    	end	    	self.locked=false	    end)	endendfunction menu:MainFlyIn(dir,_y)	self.x=screen.width*0.5-150 self.y=screen.height*0.5+_y	if self.img=="logo" or self.img=="logo0" or self.img=="menu_flower" or self.img=="menu_moon" then		if dir=='in' and self.alpha<0.5 then	    	task.New(self,function()	    		for i=0,9 do	    			self.alpha=i/9	    			task.Wait()	    		end	    		self.locked=false	    	end)	    end	    if dir=='out' and self.alpha>0.5 then	    	task.New(self,function()	    		self.locked=true	    		for i=9,0,-1 do	     			self.alpha=i/9	    			task.Wait()	    		end	    	end)	    end	else		if dir=='in' then	    	task.New(self,function()	    		for i=0,14 do	    			self.alpha=i/14	    			task.Wait()	    		end	    		self.locked=false	    	end)	    end	    if dir=='out' then	    	task.New(self,function()	    		self.locked=true	    		for i=14,0,-1 do	     			self.alpha=i/14	    			task.Wait()	    		end	    	end)	    end	endendfunction menu:SelectFly(dir)	if dir=='in' then	    self.x=screen.width*0.5 self.y=screen.height*0.5+300		task.New(self,function()		    task.MoveTo(screen.width*0.5,screen.height*0.5+200,15,2)	    end)	end	if dir=='out' then	    self.x=screen.width*0.5 self.y=screen.height*0.5+200		task.New(self,function()		    task.MoveTo(screen.width*0.5,screen.height*0.5+300,15,2)	    end)	endendfunction menu:MainChoose(dir)	if dir=='in' then		task.New(self,function()		    self.im=self.im-1			self.choose=true	    end)		task.New(self,function()		    self.Y=self.y			for i=0,5 do			    self.y=self.Y+2*sin(i*90)				task.Wait()			end			self.y=self.Y	    end)	end	if dir=='out' then		task.New(self,function()		    self.im=self.im+1			self.choose=false		end)	end	if dir=='back' then		task.New(self,function()		    self.im=self.rim		end)	endendfunction menu:MoveTo(x1,y1,x2,y2,t,mode)	self.x=x1 or self.x	self.y=y1 or self.y	task.Clear(self)	task.New(self,function() task.MoveTo(x2 or self.x,y2 or self.y,t,mode) end)end---------------------------------------------------------------------------------20170830_sc_table_sort=false--[[第一次开mod后将符卡按难度分到菜单的三个表（N、L、总）然后_sc_table按照(总)的排序--]]sc_pr_menu=Class(object)function sc_pr_menu:init(exit_func)	self.layer=LAYER_TOP	self.group=GROUP_GHOST	self.alpha=1	self.exit_func=exit_func	self.x=screen.width*0.5+700 self.y=screen.height*0.5	self.bound=false	self.locked=true--	self.npage=max(int((#_sc_table-1)/ui.menu.sc_pr_line_per_page)+1,1)	self.page=scoredata.sc_page or 0	self.pos=1	self.pos_changed=0	self.diff=1	self.mode=ran:Int(0,4)	ui.menu.sc_pr_width=600	self.sc_table={}	self.n_sc={}	self.l_sc={}	for i=1,#_sc_table do		if _editor_class[_sc_table[i][1]].difficulty=='Normal' then			if _sc_table[i][5] then				table.insert(self.n_sc,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4],_sc_table[i][5]})				table.insert(self.sc_table,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4],_sc_table[i][5]})			else				table.insert(self.n_sc,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4]})				table.insert(self.sc_table,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4],_sc_table[i][5]})			end		end	end	self.normal_card_num=#self.n_sc	for i=1,#_sc_table do		if _editor_class[_sc_table[i][1]].difficulty=='Lunatic' then			if _sc_table[i][5] then				table.insert(self.l_sc,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4],_sc_table[i][5]})				table.insert(self.sc_table,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4],_sc_table[i][5]})			else				table.insert(self.l_sc,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4]})				table.insert(self.sc_table,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4],_sc_table[i][5]})			end		end	end	self.lunatic_card_num=#self.l_sc	for i=1,#_sc_table do		if _editor_class[_sc_table[i][1]].difficulty~='Lunatic' and _editor_class[_sc_table[i][1]].difficulty~='Normal' then			if _sc_table[i][5] then				table.insert(self.sc_table,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4],_sc_table[i][5]})			else				table.insert(self.sc_table,{_sc_table[i][1],_sc_table[i][2],_sc_table[i][3],_sc_table[i][4]})			end		end	end	self.npage=max(int((max(self.normal_card_num,self.lunatic_card_num)-1)/ui.menu.sc_pr_line_per_page)+1,1)	do--		if scoredata.spell_card_hist==nil then scoredata.spell_card_hist={} end		if scoredata.spell_card_hist['Normal']==nil then scoredata.spell_card_hist['Normal']={} end		if scoredata.spell_card_hist['Lunatic']==nil then scoredata.spell_card_hist['Lunatic']={} end		if scoredata.spell_card_hist['All']==nil then scoredata.spell_card_hist['All']={} end		for i=1,#_sc_table do			if scoredata.spell_card_hist[_editor_class[_sc_table[i][1]].difficulty][_sc_table[i][2]]==nil then				scoredata.spell_card_hist[_editor_class[_sc_table[i][1]].difficulty][_sc_table[i][2]]={0,0}			end		end	end--	if scoredata.spell_card_hist['Lunatic']['核符「超新星」'][2]>0 and scoredata.spell_card_hist['Lunatic']['裂变「重水反应堆」'][2]>0 and scoredata.spell_card_hist['Lunatic']['聚合「链式反应」'][2]>0 and scoredata.spell_card_hist['Lunatic']['辐射「激发态量子」'][2]>0 and scoredata.spell_card_hist['Lunatic']['「通古斯的太阳」'][2]>0 and scoredata.spell_card_hist['Lunatic']['「质子对湮灭」'][2]>0 and scoredata.spell_card_hist['Lunatic']['「反粒子束武器」'][2]==0 then    scoredata.spell_card_hist['Lunatic']['「反粒子束武器」'][2]=1  end	if not _sc_table_sort then		_sc_table={}		for i=1,#self.sc_table do table.insert(_sc_table,self.sc_table[i]) end		_sc_table_sort=true	endendfunction sc_pr_menu:frame()	task.Do(self)	if self.timer%10==0 then New(leaf_image,ran:Float(-screen.width*0.5,screen.width*0.5),screen.height*0.5,ran:Float(1,2),ran:Float(-5,5)+270,self.mode,ran:Float(0.5,1.5)) end	if self.timer%300==0 then	    self.mode=ran:Int(0,4)	    for i,unit in UnitList(GROUP_GHOST) do	        if unit.mode then	    	    unit.mode=self.mode	    	end	    end    end	if self.locked then return end	if self.pos_changed>0 then self.pos_changed=self.pos_changed-1 end	if GetLastKey()==setting.keys.up    then self.pos=self.pos-1 PlaySound('select00',0.3) self.pos_changed=ui.menu.shake_time end	if GetLastKey()==setting.keys.down  then self.pos=self.pos+1 PlaySound('select00',0.3) self.pos_changed=ui.menu.shake_time end	if GetLastKey()==setting.keys.special then		self.diff=-self.diff		PlaySound('select00',0.3)		self.pos_changed=ui.menu.shake_time	end	self.pos=(self.pos+ui.menu.sc_pr_line_per_page-1)%ui.menu.sc_pr_line_per_page+1	if GetLastKey()==setting.keys.left  then		self.page=self.page-1		self.pos_changed=ui.menu.shake_time		PlaySound('select00',0.3)	end	if GetLastKey()==setting.keys.right then		self.page=self.page+1		self.pos_changed=ui.menu.shake_time		PlaySound('select00',0.3)	end	scoredata.sc_page=self.page	if self.diff==1 then    self.npage=max(int((self.normal_card_num-1)/ui.menu.sc_pr_line_per_page)+1,1)  else    self.npage=max(int((self.lunatic_card_num-1)/ui.menu.sc_pr_line_per_page)+1,1)  end  self.page=(self.page+self.npage)%self.npage	if KeyIsPressed'shoot'then		local index=self.pos+self.page*ui.menu.sc_pr_line_per_page--		if self.diff==-1 then index=self.pos+self.page*ui.menu.sc_pr_line_per_page+self.normal_card_num end		if self.diff==1 then			if self.n_sc[index] and self.n_sc[index][2]~='test' and scoredata.spell_card_hist['Normal'][self.n_sc[index][2]][2]~=0  then				if self.exit_func then self.exit_func(index) end				PlaySound('ok00',0.3)			else				PlaySound('invalid',0.5)			end		else			if self.l_sc[index] and self.l_sc[index][2]~='test' and scoredata.spell_card_hist['Lunatic'][self.l_sc[index][2]][2]~=0 then				index=self.pos+self.page*ui.menu.sc_pr_line_per_page+self.normal_card_num				if self.exit_func then self.exit_func(index) end				PlaySound('ok00',0.3)			else				PlaySound('invalid',0.5)			end		end	elseif KeyIsPressed'spell'then		PlaySound('cancel00',0.3)		if self.exit_func then self.exit_func(nil) end	endendfunction sc_pr_menu:render()--[[	ui.DrawMenu('View Replay',self.text,self.pos,self.x,self.y+ui.menu.line_height,self.alpha,self.timer,self.pos_changed)	SetFontState('menu','',Color(self.alpha*255,unpack(ui.menu.title_color)))	RenderText('menu',string.format('<-  page %d/%d  ->',self.page+1,self.npage),self.x,self.y-5.5*ui.menu.line_height,ui.menu.font_size,'centerpoint')	--]]	SetViewMode('ui')	SetImageState('white','',Color(0xC0000000))	RenderRect('white',self.x-ui.menu.sc_pr_width*0.5-ui.menu.sc_pr_margin,		self.x+ui.menu.sc_pr_width*0.5+ui.menu.sc_pr_margin,		self.y-ui.menu.sc_pr_line_height*(ui.menu.sc_pr_line_per_page+2)*0.5-ui.menu.sc_pr_margin,		self.y+ui.menu.sc_pr_line_height*(ui.menu.sc_pr_line_per_page+2)*0.5+ui.menu.sc_pr_margin)	local text1={} local text2={} local text3={} local text4={} local getcard={}	local offset=self.page*ui.menu.sc_pr_line_per_page	if self.diff==1 then	for i=1,ui.menu.sc_pr_line_per_page do		if self.n_sc[i+offset] and self.n_sc[i+offset][2]~='test' then			text1[i]=_editor_class[self.n_sc[i+offset][1]].name			text2[i]=self.n_sc[i+offset][2]			text3[i]=_editor_class[self.n_sc[i+offset][1]].difficulty			if scoredata.spell_card_hist['Normal'][self.n_sc[i+offset][2]][2]~=0 then				text4[i]=string.format('%03d',scoredata.spell_card_hist['Normal'][self.n_sc[i+offset][2]][1])..'/'..string.format('%03d',scoredata.spell_card_hist['Normal'][self.n_sc[i+offset][2]][2])				if scoredata.spell_card_hist['Normal'][self.n_sc[i+offset][2]][1]>0 then getcard[i]=1 else getcard[i]=0 end			else        text1[i]='？？？'        text2[i]='？？？？？？？？'        text3[i]=_editor_class[self.n_sc[i+offset][1]].difficulty				text4[i]='---/---'			end		else			if self.n_sc[i+offset] and self.n_sc[i+offset][2]=='test' then				text1[i]=_editor_class[self.n_sc[i+offset][1]].name text2[i]=' ' text3[i]=' ' text4[i]=' '			else			text1[i]='---' text2[i]='---' text3[i]='---' text4[i]='---/---'			end		end	end	else	for i=1,ui.menu.sc_pr_line_per_page do		if self.l_sc[i+offset] and self.l_sc[i+offset][2]~='test'  then			text1[i]=_editor_class[self.l_sc[i+offset][1]].name			text2[i]=self.l_sc[i+offset][2]			text3[i]=_editor_class[self.l_sc[i+offset][1]].difficulty			if scoredata.spell_card_hist['Lunatic'][self.l_sc[i+offset][2]][2]~=0 then				text4[i]=string.format('%03d',scoredata.spell_card_hist['Lunatic'][self.l_sc[i+offset][2]][1])..'/'..string.format('%03d',scoredata.spell_card_hist['Lunatic'][self.l_sc[i+offset][2]][2])				if scoredata.spell_card_hist['Lunatic'][self.l_sc[i+offset][2]][1]>0 then getcard[i]=1 else getcard[i]=0 end			else				text1[i]='？？？'        text2[i]='？？？？？？？？'        text3[i]=_editor_class[self.l_sc[i+offset][1]].difficulty				text4[i]='---/---'			end		else			if self.l_sc[i+offset] and self.l_sc[i+offset][2]=='test' then				text1[i]=_editor_class[self.l_sc[i+offset][1]].name text2[i]=' ' text3[i]=' ' text4[i]=' '			else			text1[i]='---' text2[i]='---' text3[i]='---' text4[i]='---/---'			end		end	end	end	ui.DrawMenuSCP('sc_pr','',text1,self.pos,self.x-ui.menu.sc_pr_width*0.5,self.y,self.alpha,self.timer,self.pos_changed,'left',getcard)	ui.DrawMenuSCP('sc_pr','',text2,self.pos,self.x+ui.menu.sc_pr_width*0.2,self.y,self.alpha,self.timer,self.pos_changed,'right',getcard)	ui.DrawMenuSCP('sc_pr','',text3,self.pos,self.x+ui.menu.sc_pr_width*0.5,self.y,self.alpha,self.timer,self.pos_changed,'right',getcard)	ui.DrawMenuSCP('sc_pr','',text4,self.pos,self.x+ui.menu.sc_pr_width*0.35,self.y,self.alpha,self.timer,self.pos_changed,'right',getcard)	RenderTTF('sc_pr','Spell Practice',self.x,self.x,self.y+(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,self.y+(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,Color(self.alpha*255,unpack(ui.menu.title_color)),'centerpoint')	RenderTTF('sc_pr',string.format('<-  page %d/%d  ->',self.page+1,self.npage),self.x,self.x,self.y-(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,self.y-(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,Color(self.alpha*255,unpack(ui.menu.title_color)),'centerpoint')	RenderTTF('sc_pr','“Special”键切换难度',self.x+ui.menu.sc_pr_width*0.5,self.x+ui.menu.sc_pr_width*0.5,self.y-(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,self.y-(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,Color(self.alpha*255,unpack(ui.menu.title_color)),'right','vcenter')	RenderTTF('sc_pr','练习中按L键可加残机',self.x-ui.menu.sc_pr_width*0.5,self.x+ui.menu.sc_pr_width*0.5,self.y-(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,self.y-(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,Color(self.alpha*255,unpack(ui.menu.title_color)),'left','vcenter')end-------------------------------------------achi_menu=Class(object)function achi_menu:init(exit_func)do  if scoredata.achi==nil then    scoredata.achi={}    for i=1,#_achi_table do scoredata.achi[i]=0 end  end  if scoredata.achi_common==nil then    scoredata.achi_common={}    for i=1,#_achi_table_common do scoredata.achi_common[i]=0 end  endend  local h=1 local nst=0 local lst=0  if scoredata.achi_var.graze>=5000 and scoredata.achi_common[10]~=1 then New(achievement_obj,2,10,h) h=h+1 end  if scoredata.achi_var.graze>=20000 and scoredata.achi_common[11]~=1 then New(achievement_obj,2,11,h) h=h+1 end  if scoredata.achi_var.graze>=100000 and scoredata.achi_common[12]~=1 then New(achievement_obj,2,12,h) h=h+1 end  if scoredata.angry==1 and scoredata.achi_common[34]~=1 then New(achievement_obj,2,34,h) h=h+1 end  for i=1,16 do nst=nst+scoredata.stage_clear[1][i] lst=lst+scoredata.stage_clear[2][i] end  if (nst==16 or lst==16) and scoredata.achi_common[1]~=1 then New(achievement_obj,2,1,h) h=h+1 end  if scoredata.play_timer>=216000 and scoredata.achi_common[13]~=1 then New(achievement_obj,2,13,h) end	if scoredata.play_timer>=648000 and scoredata.achi_common[14]~=1 then New(achievement_obj,2,14,h) end	if scoredata.play_timer>=1728000 and scoredata.achi_common[15]~=1 then New(achievement_obj,2,15,h) end	if scoredata.ed then New(achievement_obj,2,35,h) end	self.layer=LAYER_TOP	self.group=GROUP_GHOST	self.alpha=1	self.exit_func=exit_func	self.x=screen.width*0.5+1024 self.y=screen.height*0.5	self.bound=false	self.locked=true	self.npage=max(int((#_achi_table-1)/ui.menu.sc_pr_line_per_page)+1,1)	self.page=0	self.pos=1	self.pos_changed=0	self.ok={}	self.ok_common={}	self._mode=-1	for i=1,#_achi_table do		if scoredata.achi[i]==1 then self.ok[i]=true end	end	for i=1,#_achi_table_common do		if scoredata.achi_common[i]==1 then self.ok_common[i]=true end	endendfunction achi_menu:frame()	task.Do(self)	if self.timer>=18000 then New(achievement_obj,2,36) self.ok_common[36]=true end	if self.locked then return end	if self.pos_changed>0 then self.pos_changed=self.pos_changed-1 end	if GetLastKey()==setting.keys.up    then self.pos=self.pos-1 PlaySound('select00',0.3) self.pos_changed=ui.menu.shake_time end	if GetLastKey()==setting.keys.down  then self.pos=self.pos+1 PlaySound('select00',0.3) self.pos_changed=ui.menu.shake_time end	if GetLastKey()==setting.keys.special then		self._mode=-self._mode		PlaySound('select00',0.3)		self.pos_changed=ui.menu.shake_time	end	if self._mode==1 then self.npage=max(int((#_achi_table-1)/ui.menu.sc_pr_line_per_page)+1,1) else self.npage=max(int((#_achi_table_common-1)/ui.menu.sc_pr_line_per_page)+1,1) end	self.pos=(self.pos+ui.menu.sc_pr_line_per_page-1)%ui.menu.sc_pr_line_per_page+1	if GetLastKey()==setting.keys.left  then		self.page=self.page-1		self.pos_changed=ui.menu.shake_time		PlaySound('select00',0.3)	end	if GetLastKey()==setting.keys.right then		self.page=self.page+1		self.pos_changed=ui.menu.shake_time		PlaySound('select00',0.3)	end	self.page=(self.page+self.npage)%self.npage	if KeyIsPressed'shoot'then		local index=self.pos+self.page*ui.menu.sc_pr_line_per_page		if _achi_table[index] then--			if self.exit_func then self.exit_func(index) end			PlaySound('ok00',0.3)		else			PlaySound('invalid',0.5)		end	elseif KeyIsPressed'spell'then		PlaySound('cancel00',0.3)		if self.exit_func then self.exit_func(nil) end	endendfunction achi_menu:render()	SetViewMode('ui')	SetImageState('white','',Color(0xC0000000))	RenderRect('white',self.x-ui.menu.achi_width*0.5-ui.menu.sc_pr_margin-150,		self.x+ui.menu.achi_width*0.5+ui.menu.sc_pr_margin-150,		self.y-ui.menu.sc_pr_line_height*(ui.menu.sc_pr_line_per_page+2)*0.5-ui.menu.sc_pr_margin,		self.y+ui.menu.sc_pr_line_height*(ui.menu.sc_pr_line_per_page+2)*0.5+ui.menu.sc_pr_margin)	RenderRect('white',self.x-ui.menu.achi_width*0.5-ui.menu.sc_pr_margin+150,		self.x+ui.menu.achi_width*0.5+ui.menu.sc_pr_margin+150,		self.y-ui.menu.sc_pr_line_height*(ui.menu.sc_pr_line_per_page+2)*0.5-ui