=550 self.y=-40  h=h or 1  if mode==1 then    self.text=_achi_table[num][1]    if scoredata.achi[num]~=1 then      scoredata.achi[num]=1    else      Del(self)    end  else    self.text=_achi_table_common[num][1]    if scoredata.achi_common[num]~=1 then      scoredata.achi_common[num]=1    else      Del(self)    end  end  task.New(self,function()    task.Wait((h-1)*180)    PlaySound('trophy',1)    for i=1,30 do self.y=self.y+8/3 task.Wait(1) end    task.Wait(180)    for i=1,30 do self.y=self.y-8/3 task.Wait(1) end    Del(self)  end)endfunction achievement_obj:frame()endfunction achievement_obj:render()  task.Do(self)  SetViewMode'ui'  SetImageState('white','',Color(0x80000000))--  RenderRect('white',self.x-70,self.x+70,self.y-40,self.y+40)  Render(self.img,self.x,self.y)  RenderTTF('achittf','完成成就'..string.format('\n')..self.text,self.x+1,self.x+1,self.y-1,self.y-1,Color(0xFF000000),'centerpoint')  RenderTTF('achittf','完成成就'..string.format('\n')..self.text,self.x,self.x,self.y,self.y,Color(0xFFFFFFFF),'centerpoint')  SetViewMode'world'end--------[=[sc_pr_menu=Class(object)function sc_pr_menu:init(exit_func)	self.layer=LAYER_TOP	self.group=GROUP_GHOST	self.alpha=1	self.exit_func=exit_func	self.x=screen.width*0.5+700 self.y=screen.height*0.5	self.bound=false	self.locked=true	self.npage=max(int((#_sc_table-1)/ui.menu.sc_pr_line_per_page)+1,1)	self.page=0	self.pos=1	self.pos_changed=0	ui.menu.sc_pr_width=600	self.sc_table={}	for i=1,#_sc_table do	endendfunction sc_pr_menu:frame()	task.Do(self)	if self.locked then return end	if self.pos_changed>0 then self.pos_changed=self.pos_changed-1 end	if GetLastKey()==setting.keys.up    then self.pos=self.pos-1 PlaySound('select00',0.3) self.pos_changed=ui.menu.shake_time end	if GetLastKey()==setting.keys.down  then self.pos=self.pos+1 PlaySound('select00',0.3) self.pos_changed=ui.menu.shake_time end	self.pos=(self.pos+ui.menu.sc_pr_line_per_page-1)%ui.menu.sc_pr_li