t2,self.pos,self.x+ui.menu.sc_pr_width*0.35,self.y,self.alpha,self.timer,self.pos_changed,'right')	ui.DrawMenuTTF('sc_pr','',text3,self.pos,self.x+ui.menu.sc_pr_width*0.5,self.y,self.alpha,self.timer,self.pos_changed,'right')	RenderTTF('sc_pr','Spell Practice',self.x,self.x,self.y+(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,self.y+(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,Color(self.alpha*255,unpack(ui.menu.title_color)),'centerpoint')	RenderTTF('sc_pr',string.format('<-  page %d/%d  ->',self.page+1,self.npage),self.x,self.x,self.y-(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,self.y-(ui.menu.sc_pr_line_per_page+1)*ui.menu.sc_pr_line_height*0.5,Color(self.alpha*255,unpack(ui.menu.title_color)),'centerpoint')end--]=]simple_menu=Class(object)function simple_menu:init(title,content)	self.layer=LAYER_TOP	self.group=GROUP_GHOST	self.alpha=1	self.x=screen.width*0.5-448 self.y=screen.height*0.5	self.bound=false	self.locked=true	self.title=title	self.text={} self.func={}	for i=1,#content do self.text[i]=content[i][1] self.func[i]=content[i][2] end	self.pos=1	self.pos_pre=1	self.pos_changed=0	if content[#content][1]=='exit' then self.exit_func=content[#content][2] self.text[#content]=nil self.func[#content]=nil endendfunction simple_menu:frame()	task.Do(self)	if self.locked then return end	if GetLastKey()==setting.keys.up   then self.pos=self.pos-1 PlaySound('select00',0.3) end	if GetLastKey()==setting.keys.down then self.pos=self.pos+1 PlaySound('select00',0.3) end	self.pos=(self.pos-1+#(self.text))%(#(self.text))+1	if KeyIsPressed'shoot' and self.func[self.pos] then self.func[self.pos]() PlaySound('ok00',0.3)	elseif KeyIsPressed'spell' and self.exit_func then self.exit_func() PlaySound('cancel00',0.3) end	if self.pos_changed>0 then self.pos_changed=self.pos_changed-1 end	if self.pos_pre~=self.pos then self.pos_changed=ui.menu.shake_time end	self.pos_pre=self.posendfunction simple_menu:render()	SetViewMode('ui')	ui.DrawMenu(self.title,self.text,self.pos,self.x,self.y,self.alpha,self.timer,self.pos_changed)endsimple_image=Class(object)function simple_image:init(img,size)	self.layer=LAYER_TOP	self.group=GROUP_GHOST	self.bound=false	self.img=img self.hscale=size self.vscale=size	self.x=screen.width*0.5-448 self.y=screen.height*0.5	self.alpha=1endfunction simple_image:frame()	task.Do(self)endfunction simple_image:render()	SetViewMode('ui')	SetImageState(self.img,'',Color(self.alpha*255,255,255,255))	object.render(self)end------------------------------------------------------------LoadTTF("replayfnt", 'THlib\\UI\\font\\default_ttf', 30)LoadImageFromFile('replay_title','THlib\\UI\\replay_title.png')LoadImageFromFile('save_rep_title','THlib\\UI\\save_rep_title.png')local REPLAY_USER_NAME_MAX = 8local REPLAY_DISPLAY_FORMAT1 = "%02d %s %"..tostring(REPLAY_USER_NAME_MAX).."s %012d"local REPLAY_DISPLAY_FORMAT2 = "%02d ----/--/-- --:--:-- %"..tostring(REPLAY_USER_NAME_MAX).."s %012d"local function FetchReplaySlots()	local ret = {}	ext.replay.RefreshReplay()	for i = 1, ext.replay.GetSlotCount() do		local text={}		local slot = ext.replay.GetSlot(i)		if slot then			-- 使用第一关的时间作为录像时间			local date = os.date("!%Y/%m/%d", slot.stages[1].stageDate + setting.timezone * 3600)			-- 统计总分数			local totalScore = 0			local diff,stage_num=0,0			local tmp			for i, k in ipairs(slot.stages) do				totalScore = totalScore + slot.stages[i].score				diff=string.match(k.stageName,'^.+@(.+)$')				tmp=string.match(k.stageName,'^(.+)@.+$')				if string.match(tmp,'%d+')==nil then					stage_num=tmp				else					stage_num='St'..string.match(tmp,'%d+')				end			end			if diff=='Spell Practice' then diff='SpellCard' end			if tmp=='Spell Practice' then stage_num='SC' end			if slot.group_finish == 1 then stage_num='All' end			text = {string.format('No.%02d',i), slot.userName, date, slot.stages[1].stagePlayer, diff, stage_num}		else      text = {string.format('No.%02d',i), '--------', '----/--/--', '--------', '--------', '---'}    end--[[			text = string.format(REPLAY_DISPLAY_FORMAT1, i, date, slot.userName, totalScore)		else			text = string.format(REPLAY_DISPLAY_FORMAT2, i, "N/A", 0)		end	]]		table.insert(ret, text)	end	return retend------------------replay_saver-------------------------local _keyboard={}do  for i=65,90 do table.insert(_keyboard,i) end  for i=97,122 do table.insert(_keyboard,i) end  for i=48,57 do table.insert(_keyboard,i) end  table.insert(_keyboard,43)  table.insert(_keyboard,45)  table.insert(_keyboard,61)  table.insert(_keyboard,46)  table.insert(_keyboard,44)  table.insert(_keyboard,33)  table.insert(_keyboard,63)  table.insert(_keyboard,64)  table.insert(_keyboard,58)  table.insert(_keyboard,59)  table.insert(_keyboard,91)  table.insert(_keyboard,93)  table.insert(_keyboard,40)  table.insert(_keyboard,41)  table.insert(_keyboard,95)  table.insert(_keyboard,47)  table.insert(_keyboard,123)  table.insert(_keyboard,125)  table.insert(_keyboard,124)  table.insert(_keyboard,126)  table.insert(_keyboard,94)  for i=35,38 do table.insert(_keyboard,i) end  table.insert(_keyboard,42)  table.insert(_keyboard,92)  table.insert(_keyboard,127)  table.insert(_keyboard,34)endreplay_saver = Class(object)function replay_saver:init(stages, finish, exitCallback)	self.layer = LAYER_TOP	self.group = GROUP_GHOST	self.bound = false	self.x = screen.width * 0.5 - 700	self.y = screen.height * 0.5	self.locked = true  self.finish=finish or 0	self.stages = stages	self.exitCallback = exitCallback	self.shakeValue = 0	self.state = 0	self.state1Selected = 1	self.state1Text = FetchReplaySlots()	self.state2CursorX = 0	self.state2CursorY = 0	self.state2UserName = ""endfunction replay_saver:frame()	task.Do(self)	if self.locked then return end	if self.shakeValue > 0 then		self.shakeValue = self.shakeValue - 1	end	-- 控制逻辑	if self.state == 0 then		local lastKey = GetLastKey()		if lastKey == setting.keys.up then			self.state1Selected = max(1, self.state1Selected - 1)			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif lastKey == setting.keys.down then			self.state1Selected = min(ext.replay.GetSlotCount(), self.state1Selected + 1)			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif KeyIsPressed("shoot") then			-- 跳转到录像保存状态			self.state = 1			self.state2CursorX = 0			self.state2CursorY = 0			self.state2UserName = ""		elseif KeyIsPressed("spell") then			if self.exitCallback then				self.exitCallback()			end			PlaySound('cancel00', 0.3)		end	elseif self.state == 1 then		local lastKey = GetLastKey()		if lastKey == setting.keys.up then			self.state2CursorY = self.state2CursorY - 1			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif lastKey == setting.keys.down then			self.state2CursorY = self.state2CursorY + 1			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif lastKey == setting.keys.left then			self.state2CursorX = self.state2CursorX - 1			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif lastKey == setting.keys.right then			self.state2CursorX = self.state2CursorX + 1			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif KeyIsPressed("shoot") then			if self.state2CursorX == 12 and self.state2CursorY == 6 then				if self.state2UserName == "" then					self.state2UserName = "Anonymous"				end				-- 保存录像				ext.replay.SaveReplay(self.stages, self.state1Selected, self.state2UserName, self.finish)				if self.exitCallback then					self.exitCallback()				end				PlaySound("extend", 0.5)        end			if #self.state2UserName == REPLAY_USER_NAME_MAX then				self.state2CursorX = 12				self.state2CursorY = 6			elseif self.state2CursorX == 11 and self.state2CursorY == 6 then        if #self.state2UserName == 0 then          self.state = 0        else          self.state2UserName = string.sub(self.state2UserName, 1, -2)        end        PlaySound('cancel00', 0.3)      elseif self.state2CursorX == 10 and self.state2CursorY == 6 then        local char = string.char(0x20)        self.state2UserName = self.state2UserName..char        PlaySound('ok00', 0.3)			else				local char = string.char(_keyboard[self.state2CursorY * 13 + self.state2CursorX+1])				self.state2UserName = self.state2UserName..char				PlaySound('ok00', 0.3)			end      elseif KeyIsPressed("spell") then			if #self.state2UserName == 0 then				self.state = 0			else				self.state2UserName = string.sub(self.state2UserName, 1, -2)			end--			self.state = 0			PlaySound('cancel00', 0.3)		end		self.state2CursorX = (self.state2CursorX + 13) % 13		self.state2CursorY = (self.state2CursorY +  7) % 7	endendfunction replay_saver:render()	SetViewMode('ui')	if self.state == 0 then		ui.DrawRepText(			"replayfnt",			"save_rep_title",			self.state1Text,			self.state1Selected,			self.x,			self.y,			1,			self.timer,			self.shakeValue			)	elseif self.state == 1 then    Render("save_rep_title",self.x,self.y+ui.menu.sc_pr_line_height+15*ui.menu.sc_pr_line_height*0.5)		---- 绘制键盘		-- 未选中按键		SetFontState("replay", "", Color(255, unpack(ui.menu.unfocused_color)))		for x = 0, 12 do			for y = 0, 6 do				if x ~= self.state2CursorX or y ~= self.state2CursorY then--[[					RenderText(						"replay",						string.char(0x20 + y * 12 + x),						self.x + (x - 5.5) * ui.menu.char_width,						self.y - (y - 3.5) * ui.menu.line_height,						ui.menu.font_size,						'centerpoint'					)]]            RenderText(						"replay",						string.char(_keyboard[y * 13 + x+1]),						self.x + (x - 5.5) * ui.menu.char_width,						self.y - (y - 3.5) * ui.menu.line_height,						ui.menu.font_size,						'centerpoint'						)				end			end		end		-- 激活按键		local color = {}		local k = cos(self.timer * ui.menu.blink_speed) ^ 2		for i = 1, 3 do			color[i] = ui.menu.focused_color1[i] * k + ui.menu.focused_color2[i] * (1-k)		end		SetFontState("replay", "", Color(255, unpack(color)))		RenderText(			"replay",			string.char(_keyboard[self.state2CursorY * 13 + self.state2CursorX+1]),			self.x + (self.state2CursorX - 5.5) * ui.menu.char_width + ui.menu.shake_range * sin(ui.menu.shake_speed * self.shakeValue),			self.y - (self.state2CursorY - 3.5) * ui.menu.line_height,			ui.menu.font_size,			"centerpoint"		)		-- 标题		SetFontState("replay", "", Color(255, unpack(ui.menu.title_color)))		RenderText("replay", self.state2UserName, self.x, self.y - 5.5 * ui.menu.line_height, ui.menu.font_size, "centerpoint")	endend-----------------------------------------------------------------------------------------------------replay_loader--------------------------------------replay_loader = Class(object)function replay_loader:init(exitCallback)	self.layer = LAYER_TOP	self.group = GROUP_GHOST	self.bound = false	self.x = screen.width * 0.5 + 700	self.y = screen.height * 0.5	-- 是否可操作	self.locked = true	self.exitCallback = exitCallback	self.shakeValue = 0	self.state = 0	self.state1Selected = 1	self.state1Text = {}	self.state2Selected = 1	self.state2Text = {}	replay_loader.Refresh(self)endfunction replay_loader:Refresh()	self.state1Text = FetchReplaySlots()endfunction replay_loader:frame()	task.Do(self)	if self.locked then return end	if self.shakeValue > 0 then		self.shakeValue = self.shakeValue - 1	end	-- 控制逻辑	if self.state == 0 then		local lastKey = GetLastKey()		if lastKey == setting.keys.up then			self.state1Selected = max(1, self.state1Selected - 1)			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif lastKey == setting.keys.down then			self.state1Selected = min(ext.replay.GetSlotCount(), self.state1Selected + 1)			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif KeyIsPressed("shoot") then			-- 构造关卡列表			local slot = ext.replay.GetSlot(self.state1Selected)			if slot ~= nil then				self.state = 1				self.state2Text = {}				self.state2Selected = 1				self.shakeValue = ui.menu.shake_time				for i, v in ipairs(slot.stages) do					local stage = string.match(v.stageName,'^(.+)@.+$')					local score = string.format("%012d", v.score)					table.insert(self.state2Text, {stage, score})				end				PlaySound('ok00', 0.3)			end		elseif KeyIsPressed("spell") then			if self.exitCallback then				self.exitCallback()			end			PlaySound('cancel00', 0.3)		end	elseif self.state == 1 then		local slot = ext.replay.GetSlot(self.state1Selected)		local lastKey = GetLastKey()		if lastKey == setting.keys.up then			self.state2Selected = max(1, self.state2Selected - 1)			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif lastKey == setting.keys.down then			self.state2Selected = min(#slot.stages, self.state2Selected + 1)			self.shakeValue = ui.menu.shake_time			PlaySound('select00', 0.3)		elseif KeyIsPressed("shoot") then			-- 转场			local slot = ext.replay.GetSlot(self.state1Selected)			if self.exitCallback then				self.exitCallback(slot.path, slot.stages[self.state2Selected].stageName)			end			PlaySound('ok00', 0.3)		elseif KeyIsPressed("spell") then			self.shakeValue = ui.menu.shake_time			self.state = 0		end	endendfunction replay_loader:render()	SetViewMode('ui')	if self.state == 0 then		ui.DrawRepText(			"replayfnt",			"replay_title",			self.state1Text,			self.state1Selected,			self.x,			self.y,			1,			self.timer,			self.shakeValue			)	elseif self.state == 1 then		ui.DrawRepText2(			"replayfnt",			"replay_title",			self.state2Text,			self.state2Selected,			self.x,			self.y+120,			1,			self.timer,			self.shakeValue,			"center")	endend--------------------------------------------------------------------------------------------rank_select_menu=Class(object)function rank_select_menu:init(title,content)  LoadImageFromFile("RANK_SELECT","Thlib\\UI\\select\\RANKSELECT.png")  LoadImageFromFile("black0","Thlib\\UI\\black0.png")  LoadImageGroupFromFile("rank0","Thlib\\UI\\rank\\rank0.png",false,2,2)  LoadImageFromFile("black1","Thlib\\UI\\rank\\black1.png")	local rank_n1=New(rank_image,1,0.75)	local rank_L1=New(rank_image,3,0.75)	local RANK_SELECT=New(player_image,"RANK_SELECT",0.75,200,LAYER_TOP)    self.RANK_SELECT=RANK_SELECT	local black0=New(player_image,"black0",60,0,LAYER_BG+1)    self.black0=black0	local black1=New(player_image,"black1",0.5,0,LAYER_TOP-1)    self.black1=black1    self.rankgroup={}    self.rankgroup[1]=rank_n1    self.rankgroup[2]=rank_L1    self.rankgroup[3]=rank_n1    self.rankgroup[4]=rank_L1	self.layer=LAYER_TOP	self.group=GROUP_GHOST	self.alpha=0	self.time=-10	self.x=screen.width*0.5-448*2 self.y=screen.height*0.5	self.bound=false	self.locked=true	self.title=title	self.text={} self.func={}	for i=1,#content do self.text[i]=content[i][1] self.func[i]=content[i][2] end	self.pos=1	self.pos_pre=1	self.pos_changed=0	if content[#content][1]=='exit' then self.exit_func=content[#content][2] self.text[#content]=nil self.func[#content]=nil endendfunction rank_select_menu:frame()	task.Do(self)	if self.locked then return end	scoredata.difficulty_sellect=self.pos	if not self.new and not self.locked then		menu.SelectFly(self.RANK_SELECT,'in')        menu.AddFadeIn(self.black0)		menu.RotatingIn(self.black1,'left')		menu.Rotating(self.black1)		if self.pos==2 then            menu.RankFlyIn(self.rankgroup[self.pos],'mid')            menu.RankFlyIn(self.rankgroup[self.pos-1],'up')		else            menu.RankFlyIn(self.rankgroup[self.pos],'mid')            menu.RankFlyIn(self.rankgroup[self.pos+1],'down')		end		lastrank=self.rankgroup[self.pos]		self.pos=self.pos+1		self.pos=(self.pos-1+#(self.text))%(#(self.text))+1		lastrank2=self.rankgroup[self.pos]		self.pos=self.pos-1		self.pos=(self.pos-1+#(self.text))%(#(self.text))+1		self.new=true		self.time=-10	end	if self.time>5 then	    if GetLastKey()==setting.keys.down or GetLastKey()==setting.keys.right then    		self.pos=self.pos-1			if self.pos==0 then			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    PlaySound('select00',0.3)			    menu.RankFlyIn(lastrank,'up')			    menu.RankFlyIn(self.rankgroup[self.pos],'mid')			    lastrank=self.rankgroup[self.pos]			    self.pos=self.pos+1			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    lastrank2=self.rankgroup[self.pos]			    self.pos=self.pos-1			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    self.time=0			else			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    PlaySound('select00',0.3)			    menu.RankFlyIn(lastrank,'down')			    menu.RankFlyIn(self.rankgroup[self.pos],'mid')			    lastrank=self.rankgroup[self.pos]			    self.pos=self.pos+1			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    lastrank2=self.rankgroup[self.pos]			    self.pos=self.pos-1			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    self.time=0			end		end	    if GetLastKey()==setting.keys.up or GetLastKey()==setting.keys.left then    		self.pos=self.pos+1			if self.pos==3 then			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    PlaySound('select00',0.3)			    menu.RankFlyIn(lastrank,'down')			    menu.RankFlyIn(self.rankgroup[self.pos],'mid')			    lastrank=self.rankgroup[self.pos]			    self.pos=self.pos+1			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    lastrank2=self.rankgroup[self.pos]			    self.pos=self.pos-1			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    self.time=0			else			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    PlaySound('select00',0.3)			    menu.RankFlyIn(lastrank,'up')			    menu.RankFlyIn(self.rankgroup[self.pos],'mid')			    lastrank=self.rankgroup[self.pos]			    self.pos=self.pos+1			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    lastrank2=self.rankgroup[self.pos]			    self.pos=self.pos-1			    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			    self.time=0			end		end	    if KeyIsPressed'shoot' and self.func[self.pos] then self.func[self.pos]() PlaySound('ok00',0.3) menu.BlackOut(lastrank,'ranksave') menu.RankFlyIn(lastrank2,'out') menu.SelectFly(self.RANK_SELECT,'out') menu.RotatingOut(self.black1,'right') self.new=false	    elseif KeyIsPressed'spell' and self.exit_func then self.exit_func() PlaySound('cancel00',0.3) menu.RankFlyIn(lastrank,'out') menu.RankFlyIn(lastrank2,'out') menu.SelectFly(self.RANK_SELECT,'out') menu.RotatingOut(self.black1,'right') menu.AddFadeOut(self.black0) self.new=false end	    if self.pos_changed>0 then self.pos_changed=self.pos_changed-1 end	    if self.pos_pre~=self.pos then self.pos_changed=ui.menu.shake_time end	    self.pos_pre=self.pos	else	    self.time=self.time+1	endendfunction rank_select_menu:render()	SetViewMode('ui')endrank_image=Class(object)function rank_image:init(im,size)	self.layer=LAYER_TOP	self.group=GROUP_GHOST	self.bound=false	self.im=im	self.img="rank0"..self.im+1	self.hscale=size self.vscale=size	self.size=size	self.Hscale=1 self.Vscale=1	self.x=screen.width*0.5 self.y=screen.height*0.5-100	self.alpha=0	self.R=1	self.G=1	self.B=1	self.stage_clear=0	for i=1,16 do	    self.stage_clear=self.stage_clear+scoredata.stage_clear[self.im/2+1/2][i]	end	if self.stage_clear==16 then self.clear=true else self.clear=false end	if self.clear then New(stage_clear_image,self) endendfunction rank_image:frame()	task.Do(self)	self.hscale=self.Hscale*self.size 	self.vscale=self.Vscale*self.size	if self.x>=screen.width*0.5-25 and self.x<=screen.width*0.5+25 and self.y>=screen.height*0.5-25 and self.y<=screen.height*0.5+25 then self.img="rank0"..self.im elseif not self.imglock then self.img="rank0"..self.im+1 end