lyIn(self.maingroup[1],'in',0-50+30)    		menu.MainFlyIn(self.maingroup[2],'in',-30-50+30)    		menu.MainFlyIn(self.maingroup[3],'in',-60-50+30)    		menu.MainFlyIn(self.maingroup[4],'in',-90-50+30)    		menu.MainFlyIn(self.maingroup[5],'in',-120-50+30)    		menu.MainFlyIn(self.maingroup[6],'in',-150-50+30)    		menu.MainFlyIn(self.maingroup[7],'in',-180-50+30)    		menu.MainChoose(self.maingroup[1],'back')    		menu.MainChoose(self.maingroup[2],'back')    		menu.MainChoose(self.maingroup[3],'back')    		menu.MainChoose(self.maingroup[4],'back')    		menu.MainChoose(self.maingroup[5],'back')    		menu.MainChoose(self.maingroup[6],'back')    		menu.MainChoose(self.maingroup[7],'back')			menu.MainFlyIn(self.logo0,'out',120)			menu.MainFlyIn(self.menu_moon,'out',120)			menu.MainFlyIn(self.menu_flower,'out',120)			menu.MainFlyIn(self.logo,'in',120)    		lastmain=self.maingroup[self.pos]    		menu.MainChoose(self.maingroup[self.pos],'in')			self.flyin=true		end		if self.alpha<0.9 then		    self.alpha=self.alpha+1/29		else		    self.alpha=1    		self.new=true    		self.time=0			self.out=false			self.flyin=false		end	end	if self.time>5 then	    if GetLastKey()==setting.keys.up then    		self.pos=self.pos-1			self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			PlaySound('select00',0.3)	    	menu.MainChoose(lastmain,'out')			menu.MainChoose(self.maingroup[self.pos],'in')		    lastmain=self.maingroup[self.pos]			self.time=5		end	    if GetLastKey()==setting.keys.down then    		self.pos=self.pos+1			self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			self.pos=(self.pos-1+#(self.text))%(#(self.text))+1			PlaySound('select00',0.3)	    	menu.MainChoose(lastmain,'out')			menu.MainChoose(self.maingroup[self.pos],'in')		    lastmain=self.maingroup[self.pos]			self.time=5		end	    if KeyIsPressed'shoot' and self.func[self.pos] then        if self.pos==2 then        if (self.nst==16 or self.lst==16) then        self.func[self.pos]()        PlaySound('ok00',0.3)        menu.MainFlyIn(self.maingroup[1],'out',0-50+30)        menu.MainFlyIn(self.maingroup[2],'out',-30-50+30)        menu.MainFlyIn(self.maingroup[3],'out',-60-50+30)        menu.MainFlyIn(self.maingroup[4],'out',-90-50+30)        menu.MainFlyIn(self.maingroup[5],'out',-120-50+30)        menu.MainFlyIn(self.maingroup[6],'out',-150-50+30)        menu.MainFlyIn(self.maingroup[7],'out',-180-50+30)        menu.BlackOut(lastmain,'nomal')        menu.MainChoose(lastmain,'out')        menu.MainFlyIn(self.logo,'out',120)        self.new=false        self.out=true        else PlaySound('invalid',0.1) end end        if self.pos~=2 then        self.func[self.pos]()        PlaySound('ok00',0.3)        menu.MainFlyIn(self.maingroup[1],'out',0-50+30)        menu.MainFlyIn(self.maingroup[2],'out',-30-50+30)        menu.MainFlyIn(self.maingroup[3],'out',-60-50+30)        menu.MainFlyIn(self.maingroup[4],'out',-90-50+30)        menu.MainFlyIn(self.maingroup[5],'out',-120-50+30)        menu.MainFlyIn(self.maingroup[6],'out',-150-50+30)        menu.MainFlyIn(self.maingroup[7],'out',-180-50+30)        menu.BlackOut(lastmain,'nomal')        menu.MainChoose(lastmain,'out')        menu.MainFlyIn(self.logo,'out',120)        self.new=false        self.out=true        end	    elseif KeyIsPressed'spell' and self.exit_func then		    self.exit_func()		    PlaySound('cancel00',0.3)			menu.MainChoose(lastmain,'out')		    menu.MainFlyIn(self.maingroup[1],'out',0-50+30)			menu.MainFlyIn(self.maingroup[2],'out',-30-50+30)			menu.MainFlyIn(self.maingroup[3],'out',-60-50+30)			menu.MainFlyIn(self.maingroup[4],'out',-90-50+30)			menu.MainFlyIn(self.maingroup[5],'out',-120-50+30)			menu.MainFlyIn(self.maingroup[6],'out',-150-50+30)			menu.MainFlyIn(self.maingroup[7],'out',-180-50+30)			self.new=false		end	    if self.pos_changed>0 then self.pos_changed=self.pos_changed-1 end	    if self.pos_pre~=self.pos then self.pos_ch