.width*0.5+x self.y=screen.height*0.5+y	self.alpha=0	self.al1=1	self.size=ran:Float(0.2,1)	self.hscale=size self.vscale=size	self.di=ran:Float(1,3)	task.New(self,function()		task.New(self,function()			for i=1,300 do self.hscale=sin(self.di*i)*size task.Wait(1) end		end)		for i=1,15 do self.alpha=self.alpha+1/15 task.Wait(1) end		for j=1,180 do task.Wait(1) end		for i=1,30 do self.alpha=self.alpha-1/30 task.Wait(1) end		Del(self)	end)endfunction leaf_image:frame()	task.Do(self)endfunction leaf_image:render()	SetViewMode('ui')	if self.rmode==self.mode then	    self.al1=1	    SetImageState(self.img,'mul+add',Color(self.alpha*255/2,255,255,255))		Render("menu_leaves"..self.rmode+1,self.x,self.y,self.rot,self.hscale,self.vscale)	else	    self.img="menu_leaves"..self.mode+1	    SetImageState("menu_leaves"..self.rmode+1,'mul+add',Color(self.al1*self.alpha*255/2,255,255,255))	    SetImageState("menu_leaves"..self.mode+1,'mul+add',Color((1-self.al1)*self.alpha*255/2,255,255,255))		Render("menu_leaves"..self.rmode+1,self.x,self.y,self.rot,self.hscale,self.vscale)		Render("menu_leaves"..self.mode+1,self.x,self.y,self.rot,self.hscale,self.vscale)		if self.al1>0.01 then self.al1=self.al1-1/29 else self.al1=0 self.img="menu_leaves"..self.mode+1 self.rmode=self.mode end	endendmain_image=Class(object)function main_image:init(im,size)	self.layer=LAYER_TOP	self.group=GROUP_GHOST	self.bound=false	self.im=im	self.rim=im	self.img="title0"..self.im	self.hscale=size	self.vscale=size	self.x=screen.width*0.5-448 self.y=screen.height*0.5-100	self.alpha=0	self.R=1	self.G=1	self.B=1	self.time=90endfunction main_image:frame()	task.Do(self)	self.img="title0"..self.im	if self.choose then self.time=self.time+10 self.B=(sin(self.time)*105/2+150+105/2)/255 else self.R=1 self.G=1 self.B=1 self.time=90 endendfunction main_image:render()	SetViewMode('ui')	SetImageState(self.img,'',Color(self.alpha*255,self.R*255,self.G*255,self.B*255))	obj