self.h=self.h+350 PlaySound('select00',0.3) else self.h=3100 PlaySound('invalid',0.1) self.time=0 end end	    self.h=min(3100,max(0,self.h))	    self.pos=(self.pos-1+#(self.text))%(#(self.text))+1	    if KeyIsPressed'spell' and self.exit_func then self.exit_func() PlaySound('cancel00',0.3) menu.SelectFly(self.MANUAL_title,'out') self.new=false self.out=true menu.AddFadeOut(self.black0) end	    if self.pos_changed>0 then self.pos_changed=self.pos_changed-1 end	    if self.pos_pre~=self.pos then self.pos_changed=ui.menu.shake_time end	    self.pos_pre=self.pos	end	self.time=self.time+1endfunction manual_menu:render()	SetViewMode('ui')	RenderTexture("manual","",	{screen.width*0.5-225,screen.height*0.5-150-30,0.5,0,self.h+350,Color(self.alpha*255,255,255,255)},	{screen.width*0.5-225,screen.height*0.5-200-30,0.5,0,self.h+400,Color(0,255,255,255)},	{screen.width*0.5+225,screen.height*0.5-200-30,0.5,450,self.h+400,Color(0,255,255,255)},	{screen.width*0.5+225,screen.height*0.5-150-30,0.5,450,self.h+350,Color(self.alpha*255,255,255,255)})	RenderTexture("manual","",	{screen.width*0.5-225,screen.height*0.5-150-30,0.5,0,self.h+350,Color(self.alpha*255,255,255,255)},	{screen.width*0.5-225,screen.height*0.5+150-30,0.5,0,self.h+50,Color(self.alpha*255,255,255,255)},	{screen.width*0.5+225,screen.height*0.5+150-30,0.5,450,self.h+50,Color(self.alpha*255,255,255,255)},	{screen.width*0.5+225,screen.height*0.5-150-30,0.5,450,self.h+350,Color(self.alpha*255,255,255,255)})	RenderTexture("manual","",	{screen.width*0.5-225,screen.height*0.5+150-30,0.5,0,self.h+50,Color(self.alpha*255,255,255,255)},	{screen.width*0.5-225,screen.height*0.5+200-30,0.5,0,self.h,Color(0,255,255,255)},	{screen.width*0.5+225,screen.height*0.5+200-30,0.5,450,self.h,Color(0,255,255,255)},	{screen.width*0.5+225,screen.height*0.5+150-30,0.5,450,self.h+50,Color(self.alpha*255,255,255,255)})	endstage_select_menu=Class(object)function stage_select_menu:init(title,content)  LoadImage