),1)][self.number]==1 then self.clear=true else self.clear=false self.choose=false end	end	if self.clear and self.sty=='name' and not self.choose then New(stage_clear_image,self) self.choose=true endendfunction stage_image:render()	SetViewMode('ui')	SetImageState(self.img,'',Color(self.alpha*255,255*self.R,255*self.G,255*self.B))	object.render(self)endstage_picture_image=Class(object)function stage_picture_image:init(im,size,layer,number)	self.layer=layer	self.group=GROUP_GHOST	self.bound=false	self.img="stage_picture"..im	SetImageCenter("stage_picture"..im,-20,150)	SetImageCenter("stage_picture"..im+1,-20,150)	self.hscale=size self.vscale=size	self.size=size	self.Hscale=1 self.Vscale=1	self.x=screen.width*0.5 self.y=screen.height*0.5	self.alpha=0	self.R=1	self.G=1	self.B=1	self.im=im	self.number=numberendfunction stage_picture_image:frame()	task.Do(self)	self.hscale=self.Hscale*self.size 	self.vscale=self.Vscale*self.size	if self.number<=16 then	if scoredata.stage_clear[max(min(scoredata.difficulty_sellect,2),1)][self.number]==1 then self.clear=true else self.clear=false end	end	if self.clear then self.img="stage_picture"..self.im+1 else self.img="stage_picture"..self.im endendfunction stage_picture_image:render()	SetViewMode('ui')	SetImageState(self.img,'',Color(self.alpha*255,255*self.R,255*self.G,255*self.B))	object.render(self)end  LoadImageFromFile("stage_clear","Thlib\\UI\\stage_clear.png")stage_clear_image=Class(object)function stage_clear_image:init(master)	self.layer=LAYER_TOP+5	self.group=GROUP_GHOST	self.bound=false	self.img="stage_clear"	self.hscale=0.5 self.vscale=0.5	self.master=master	self.Hscale=1 self.Vscale=1	self.x=screen.width*0.5 self.y=screen.height*0.5+100	self.alpha=0	self.R=1	self.G=1	self.B=1	self.master=masterendfunction stage_clear_image:frame()	task.Do(self)	if scoredata.stage_clear[max(min(scoredata.difficulty_sellect,2),1)][self.master.number]==1 then else Del(self) end	--(fu85,25)	self.x=self.master.x-140*self.master.Hscale self.y=self.master.y+40*self.master.Hscale	self.R=self.master.R self.G=self.master.G self.B=self.master.B	self.hscale=self.master.Hscale/2 	self.vscale=self.master.Vscale/2	if self.master.x<screen.width*0.5+50 and self.master.x>screen.width*0.5-50 then	    if self.alpha<0.9 then		    self.alpha=self.alpha+1/29			self.rot=60-60*sin(90*self.alpha)+10			self.hscale=1/2*sin(90*self.alpha)		else		    self.alpha=1			self.rot=0+10			self.hscale=1/2		end	elseif not self.master.imglock then	    if self.alpha>0.01 then		    self.alpha=self.alpha-1/29			self.rot=-60+60*sin(90*self.alpha)+10			self.hscale=1/2*sin(90*self.alpha)		else		    self.alpha=0			self.rot=-60+10			self.hscale=0		end	endendfunction stage_clear_image:render()	SetViewMode('ui')	SetImageState(self.img,'',Color(self.master.alpha*self.alpha*255,255*self.R,255*self.G,255*self.B))	object.render(self)end